// Per-variant data shapes, extracted from the SseWireEvent discriminated
// union by its `type` tag. The wire event type tag and the shape on the
// `data:` line are two sides of the same fact — the tag goes in the SSE
// `event:` line and the remaining fields go in the `data:` JSON. Using
// `Extract` means the client's `addEventListener('init', ...)` handler
// is guaranteed by TSC to consume a payload matching exactly the `init`
// variant of `SseWireEvent`.
export type SseInitData = Omit<Extract<SseWireEvent, { type: 'init' }>, 'type'>;
export type SseMessageData = Omit<Extract<SseWireEvent, { type: 'message' }>, 'type'>;
export type SseMessageUpdatedData = Omit<
  Extract<SseWireEvent, { type: 'message_updated' }>,
  'type'
>;
export type SseStateChangeData = Omit<
  Extract<SseWireEvent, { type: 'state_change' }>,
  'type'
>;
export type SseTokenData = Omit<Extract<SseWireEvent, { type: 'token' }>, 'type'>;
export type SseLlmFirstByteData = Omit<
  Extract<SseWireEvent, { type: 'llm_first_byte' }>,
  'type'
>;
export type SseLlmAttemptData = Omit<
  Extract<SseWireEvent, { type: 'llm_attempt' }>,
  'type'
>;
export type SseAgentDoneData = Omit<Extract<SseWireEvent, { type: 'agent_done' }>, 'type'>;
export type { LlmAttemptReason } from './LlmAttemptReason';
export type SseConversationBecameTerminalData = Omit<
  Extract<SseWireEvent, { type: 'conversation_became_terminal' }>,
  'type'
>;
export type SseConversationUpdateData = Omit<
  Extract<SseWireEvent, { type: 'conversation_update' }>,
  'type'
>;
export type SseErrorData = Omit<Extract<SseWireEvent, { type: 'error' }>, 'type'>;
export type SseConversationHardDeletedData = Omit<
  Extract<SseWireEvent, { type: 'conversation_hard_deleted' }>,
  'type'
>;
export type SseBrowserSessionStateData = Omit<
  Extract<SseWireEvent, { type: 'browser_session_state' }>,
  'type'
>;
export type SseSteerMessageQueuedData = Omit<
  Extract<SseWireEvent, { type: 'steer_message_queued' }>,
  'type'
>;
export type SseRateLimitSnapshotData = Omit<
  Extract<SseWireEvent, { type: 'rate_limit_snapshot' }>,
  'type'
>;
export type SseWorkScopeUpdateData = Omit<
  Extract<SseWireEvent, { type: 'work_scope_update' }>,
  'type'
>;

// Chain Q&A wire-event data shapes (Phoenix Chains v1). Same Extract +
// Omit<…, 'type'> pattern as the conversation-scoped SSE events above.
// Phase 4 will wire matching valibot schemas with `satisfies
// v.GenericSchema<unknown, ChainQa*Data>` so any Rust-side change tcs as a
// schema mismatch.
export type ChainQaTokenData = Omit<
  Extract<ChainSseWireEvent, { type: 'chain_qa_token' }>,
  'type'
>;
export type ChainQaCompletedData = Omit<
  Extract<ChainSseWireEvent, { type: 'chain_qa_completed' }>,
  'type'
>;
export type ChainQaFailedData = Omit<
  Extract<ChainSseWireEvent, { type: 'chain_qa_failed' }>,
  'type'
>;
